const createDriverIcon = (type: string) => {
  let emoji = '🛵';
  if (type === 'CAR') emoji = '🚗';
  if (type === 'TOKTOK') emoji = '🛺';
  return L.divIcon({
    html: `<div class="bg-white p-2 rounded-full shadow-2xl border-4 border-emerald-500 animate-pulse text-xl flex items-center justify-center">${emoji}</div>`,
    className: 'custom-driver-icon',
    iconSize: [45, 45],
    iconAnchor: [22, 22]
  });
};

const userIcon = L.divIcon({
  html: `<div class="bg-white p-2 rounded-full shadow-lg border-4 border-blue-500 text-lg flex items-center justify-center">👤</div>`,
  className: 'user-live-icon',
  iconSize: [40, 40],
  iconAnchor: [20, 20]
});

const pickupIcon = L.divIcon({
  html: `<div class="bg-white p-2 rounded-full shadow-lg border-4 border-rose-500 text-lg flex items-center justify-center">📍</div>`,
  className: 'pickup-icon',
  iconSize: [40, 40],
  iconAnchor: [20, 20]
});

const MapAutoFit: React.FC<{ points: [number, number][] }> = ({ points }) => {
  const map = useMap();
  useEffect(() => {
    if (points.length > 1) {
      const bounds = L.latLngBounds(points);
      map.fitBounds(bounds, { padding: [70, 70] });
    }
  }, [points, map]);
  return null;
};

const CourierDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'HOME' | 'MAP' | 'ACTIVITY' | 'PROFILE'>('HOME');
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [isOnline, setIsOnline] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showOfferInput, setShowOfferInput] = useState<string | null>(null);
  const [offerPrice, setOfferPrice] = useState<string>('');
  const [showChat, setShowChat] = useState(false);

  // GPS & Routing
  const [currentLocation, setCurrentLocation] = useState({ lat: 30.556, lng: 31.008 });
  const [customerLocation, setCustomerLocation] = useState<{lat: number, lng: number} | null>(null);
  const [routeGeometry, setRouteGeometry] = useState<[number, number][]>([]);
  const watchId = useRef<number | null>(null);

  useEffect(() => {
    if (isOnline && "geolocation" in navigator) {
      watchId.current = navigator.geolocation.watchPosition(
        (pos) => {
          const newLoc = { lat: pos.coords.latitude, lng: pos.coords.longitude };
          setCurrentLocation(newLoc);
          updateDoc(doc(db, "users", user.id), { location: { ...newLoc, updatedAt: Date.now() } });
        },
        undefined, { enableHighAccuracy: true }
      );
    }
    return () => { if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current); };
  }, [isOnline, user.id]);

  useEffect(() => {
    if (activeOrder) {
      // جلب المسار الفعلي
      const targetLat = activeOrder.status === OrderStatus.ACCEPTED ? activeOrder.pickup.lat : activeOrder.dropoff.lat;
      const targetLng = activeOrder.status === OrderStatus.ACCEPTED ? activeOrder.pickup.lng : activeOrder.dropoff.lng;

      getRouteGeometry(currentLocation.lat, currentLocation.lng, targetLat, targetLng)
        .then(setRouteGeometry);

      if (activeOrder.customerId) {
        return onSnapshot(doc(db, "users", activeOrder.customerId), (doc) => {
          if (doc.exists() && doc.data().location) setCustomerLocation(doc.data().location);
        });
      }
    } else {
      setRouteGeometry([]);
    }
  }, [activeOrder?.status, activeOrder?.id, currentLocation]);

  useEffect(() => {
    if (!isOnline || user.status !== 'APPROVED') return;
    const unsubAvailable = onSnapshot(query(collection(db, "orders"), where("status", "==", OrderStatus.WAITING_FOR_OFFERS)), (snapshot) => {
      setAvailableOrders(snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[]);
    });
    const unsubActive = onSnapshot(query(collection(db, "orders"), where("driverId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
    return () => { unsubAvailable(); unsubActive(); };
  }, [isOnline, user.id, user.status]);

  const handleSendOffer = async (orderId: string) => {
    const price = parseFloat(offerPrice);
    if (!price || isSubmitting) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "offers"), {
        orderId, driverId: user.id, driverName: user.name, driverPhone: user.phone,
        driverRating: 5.0, driverPhoto: user.photoURL || null,
        vehicleType: user.vehicleType || 'TOKTOK', price, createdAt: Date.now()
      });
      setShowOfferInput(null); setOfferPrice('');
    } catch (e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  const updateOrderStatus = async (status: OrderStatus) => {
    if (!activeOrder || isSubmitting) return;
    setIsSubmitting(true);
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), { status, ...(status === OrderStatus.DELIVERED ? { deliveredAt: Date.now() } : {}) });
    } catch (e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  if (user.status !== 'APPROVED') return <div className="p-20 text-center font-black">حسابك بانتظار التفعيل</div>;
  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('HOME')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onBack={() => setActiveView('HOME')} onUpdate={() => {}} />;

  return (
    <div className="rh-layout relative">
      {activeView === 'MAP' && (
        <div className="map-page-container animate-in fade-in h-full w-full">
           <div className="absolute top-10 left-6 right-6 z-[1010] flex justify-between">
              <button onClick={() => setActiveView('HOME')} className="p-4 bg-white rounded-3xl shadow-xl active:scale-90"><ArrowRight /></button>
           </div>
           <MapContainer center={[currentLocation.lat, currentLocation.lng]} zoom={14} zoomControl={false} className="h-full w-full">
              <TileLayer url="https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png" />
              <Marker position={[currentLocation.lat, currentLocation.lng]} icon={createDriverIcon(user.vehicleType || 'TOKTOK')} />
              {activeOrder && (
                <>
                  <Marker position={[activeOrder.pickup.lat, activeOrder.pickup.lng]} icon={pickupIcon} />
                  <Marker position={[activeOrder.dropoff.lat, activeOrder.dropoff.lng]} />
                  {routeGeometry.length > 0 && <Polyline positions={routeGeometry} color="#10b981" weight={6} opacity={0.8} />}
                </>
              )}
              <MapAutoFit points={[[currentLocation.lat, currentLocation.lng], ...(activeOrder ? [[activeOrder.pickup.lat, activeOrder.pickup.lng] as [number, number], [activeOrder.dropoff.lat, activeOrder.dropoff.lng] as [number, number]] : [])]} />
           </MapContainer>
        </div>
      )}

      <div className={`page-container ${activeView === 'MAP' ? 'hidden' : 'block'}`}>
        <div className="p-6 md:p-12 space-y-8 max-w-2xl mx-auto">
            <div className={`p-8 rounded-[3rem] text-white flex justify-between items-center shadow-2xl transition-all ${isOnline ? 'bg-emerald-600' : 'bg-slate-950'}`}>
               <div><h2 className="text-3xl font-black">{isOnline ? 'نشط' : 'متوقف'}</h2><p className="text-[10px] opacity-60 uppercase mt-1">كابتن وصلها</p></div>
               <button onClick={() => setIsOnline(!isOnline)} className={`p-6 rounded-[2rem] active:scale-90 ${isOnline ? 'bg-white text-emerald-600' : 'bg-emerald-500 text-white'}`}><Power /></button>
            </div>

            {activeOrder ? (
               <div className="bg-white rounded-[3.5rem] shadow-2xl border-t-8 border-t-emerald-500 p-8 space-y-8">
                  <div className="flex justify-between items-center">
                     <span className="bg-emerald-50 text-emerald-600 px-5 py-2 rounded-full text-[10px] font-black">{activeOrder.status}</span>
                     <p className="text-4xl font-black text-slate-950">{activeOrder.price} ج.م</p>
                  </div>
                  <div className="space-y-6 text-right">
                     <div className="flex gap-4 flex-row-reverse"><div className="bg-slate-50 p-4 rounded-2xl text-emerald-600"><MapPin /></div><div className="flex-1"><p className="text-[9px] text-slate-400">نقطة الاستلام</p><p className="font-black text-lg">{activeOrder.pickup?.villageName}</p></div></div>
                     <div className="flex gap-4 flex-row-reverse"><div className="bg-rose-50 p-4 rounded-2xl text-rose-600"><Navigation2 /></div><div className="flex-1"><p className="text-[9px] text-slate-400">وجهة التوصيل</p><p className="font-black text-lg">{activeOrder.dropoff?.villageName}</p></div></div>
                  </div>
                  <button onClick={() => setActiveView('MAP')} className="w-full bg-emerald-500 text-white py-6 rounded-3xl font-black flex items-center justify-center gap-4"><Crosshair /> تتبع المسار الفعلي</button>
                  <div className="grid grid-cols-2 gap-4">
                     <a href={`tel:${activeOrder.customerPhone}`} className="bg-slate-900 text-white py-5 rounded-3xl font-black flex items-center justify-center gap-3"><PhoneCall /> اتصال</a>
                     <button onClick={() => setShowChat(true)} className="bg-white border-2 border-slate-100 text-slate-900 py-5 rounded-3xl font-black flex items-center justify-center gap-3"><MessageCircle /> دردشة</button>
                  </div>
                  <button onClick={() => updateOrderStatus(activeOrder.status === OrderStatus.ACCEPTED ? OrderStatus.PICKED_UP : OrderStatus.DELIVERED)} disabled={isSubmitting} className="w-full bg-emerald-600 text-white py-7 rounded-[2rem] font-black text-lg shadow-xl">{isSubmitting ? <Loader2 className="animate-spin mx-auto" /> : activeOrder.status === OrderStatus.ACCEPTED ? 'تأكيد الاستلام' : 'تأكيد التوصيل'}</button>
               </div>
            ) : (
               <div className="space-y-6">
                  {availableOrders.map(o => (
                     <div key={o.id} className="bg-white p-8 rounded-[3.5rem] border-2 border-slate-50 shadow-xl space-y-6">
                        <div className="flex justify-between items-start text-right">
                           <div><p className="text-xl font-black">{o.pickup?.villageName} ← {o.dropoff?.villageName}</p><span className="text-[10px] bg-emerald-50 text-emerald-600 px-3 py-1 rounded-full">{o.requestedVehicleType}</span></div>
                           <div className="bg-slate-950 text-emerald-400 p-4 rounded-2xl font-black text-2xl">{o.price}</div>
                        </div>
                        <button onClick={() => { setShowOfferInput(o.id); setOfferPrice(o.price.toString()); }} className="w-full bg-slate-900 text-white py-6 rounded-3xl font-black shadow-xl flex items-center justify-center gap-4"><Zap className="text-emerald-400" /> تقديم عرض سعر</button>
                     </div>
                  ))}
               </div>
            )}
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-xl border-t border-slate-100 p-6 flex justify-around items-center z-[150] rounded-t-[3rem]">
         {[{id: 'HOME', icon: <Home />, label: 'الرئيسية'}, {id: 'ACTIVITY', icon: <History />, label: 'سجلي'}, {id: 'PROFILE', icon: <UserIcon />, label: 'حسابي'}].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-1 ${activeView === tab.id ? 'text-emerald-600 scale-110' : 'text-slate-300'}`}><div className={`p-3 rounded-2xl ${activeView === tab.id ? 'bg-emerald-50 shadow-inner' : ''}`}>{tab.icon}</div><span className="text-[9px] font-black uppercase tracking-widest">{tab.label}</span></button>
         ))}
      </nav>
    </div>
  );
};

