});

const CourierDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'HOME' | 'MAP' | 'ACTIVITY' | 'PROFILE'>('HOME');
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [isOnline, setIsOnline] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showOfferInput, setShowOfferInput] = useState<string | null>(null);
  const [offerPrice, setOfferPrice] = useState<string>('');
  const [showChat, setShowChat] = useState(false);

  // Map Tracking
  const [currentLocation, setCurrentLocation] = useState({ lat: 30.556, lng: 31.008 });
  const [routeGeometry, setRouteGeometry] = useState<[number, number][]>([]);
  const watchId = useRef<number | null>(null);

  useEffect(() => {
    if (isOnline && "geolocation" in navigator) {
      watchId.current = navigator.geolocation.watchPosition(
        (pos) => {
          const newLoc = { lat: pos.coords.latitude, lng: pos.coords.longitude };
          setCurrentLocation(newLoc);
          updateDoc(doc(db, "users", user.id), { location: { ...newLoc, updatedAt: Date.now() } });
        },
        undefined, { enableHighAccuracy: true }
      );
    }
    return () => { if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current); };
  }, [isOnline, user.id]);

  useEffect(() => {
    if (activeOrder) {
      const destLat = activeOrder.status === OrderStatus.ACCEPTED ? activeOrder.pickup.lat : activeOrder.dropoff.lat;
      const destLng = activeOrder.status === OrderStatus.ACCEPTED ? activeOrder.pickup.lng : activeOrder.dropoff.lng;
      getRouteGeometry(currentLocation.lat, currentLocation.lng, destLat, destLng).then(setRouteGeometry);
    } else {
      setRouteGeometry([]);
    }
  }, [activeOrder?.status, currentLocation]);

  useEffect(() => {
    if (!isOnline || user.status !== 'APPROVED') return;
    const unsubAvailable = onSnapshot(query(collection(db, "orders"), where("status", "==", OrderStatus.WAITING_FOR_OFFERS)), (snapshot) => {
      setAvailableOrders(snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[]);
    });
    const unsubActive = onSnapshot(query(collection(db, "orders"), where("driverId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
    return () => { unsubAvailable(); unsubActive(); };
  }, [isOnline, user.id, user.status]);

  const handleSendOffer = async (order: Order) => {
    const price = parseFloat(offerPrice);
    if (!price || isSubmitting) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "offers"), {
        orderId: order.id, driverId: user.id, driverName: user.name, driverPhone: user.phone,
        driverRating: 5.0, driverPhoto: user.photoURL || null,
        vehicleType: user.vehicleType || 'TOKTOK', price, createdAt: Date.now()
      });
      setShowOfferInput(null); setOfferPrice('');
    } finally { setIsSubmitting(false); }
  };

  const updateOrderStatus = async (status: OrderStatus) => {
    if (!activeOrder || isSubmitting) return;
    setIsSubmitting(true);
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), { status, ...(status === OrderStatus.DELIVERED ? { deliveredAt: Date.now() } : {}) });
    } finally { setIsSubmitting(false); }
  };

  if (user.status !== 'APPROVED') return <div className="p-20 text-center font-black">حسابك بانتظار التفعيل</div>;
  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('HOME')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onBack={() => setActiveView('HOME')} onUpdate={() => {}} />;

  return (
    <div className="rh-layout relative">
      {activeView === 'MAP' && activeOrder && (
        <div className="absolute inset-0 z-[1000] bg-white">
           <div className="absolute top-8 left-6 right-6 z-[1010] flex justify-between">
              <button onClick={() => setActiveView('HOME')} className="p-4 bg-white rounded-3xl shadow-2xl border border-slate-100"><ArrowRight /></button>
              <div className="bg-emerald-600 text-white px-6 py-3 rounded-2xl font-black shadow-xl">تتبع المسار الفعلي</div>
           </div>
           <MapContainer center={[currentLocation.lat, currentLocation.lng]} zoom={15} zoomControl={false} className="h-full w-full">
              <TileLayer url="https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png" />
              <Marker position={[currentLocation.lat, currentLocation.lng]} icon={driverIcon} />
              <Marker position={[activeOrder.pickup.lat, activeOrder.pickup.lng]} />
              <Marker position={[activeOrder.dropoff.lat, activeOrder.dropoff.lng]} />
              {routeGeometry.length > 0 && <Polyline positions={routeGeometry} color="#10b981" weight={6} opacity={0.8} />}
              <MapAutoFit points={[[currentLocation.lat, currentLocation.lng], [activeOrder.pickup.lat, activeOrder.pickup.lng], [activeOrder.dropoff.lat, activeOrder.dropoff.lng]]} />
           </MapContainer>
        </div>
      )}

      <div className="page-container no-scrollbar">
        <div className="p-6 md:p-12 space-y-8 max-w-2xl mx-auto">
            <div className={`p-8 rounded-[3rem] text-white flex justify-between items-center shadow-2xl transition-all ${isOnline ? 'bg-emerald-600' : 'bg-slate-950'}`}>
               <div><h2 className="text-3xl font-black">{isOnline ? 'نشط الآن' : 'متوقف'}</h2><p className="text-[10px] opacity-60 uppercase mt-1">كابتن وصلها أشمون</p></div>
               <button onClick={() => setIsOnline(!isOnline)} className={`p-6 rounded-[2rem] shadow-2xl active:scale-90 transition-all ${isOnline ? 'bg-white text-emerald-600' : 'bg-emerald-500 text-white'}`}><Power /></button>
            </div>

            {activeOrder ? (
               <div className="bg-white rounded-[3.5rem] shadow-2xl border-t-8 border-t-emerald-500 p-8 space-y-8 animate-in zoom-in">
                  <div className="flex justify-between items-center">
                     <span className="bg-emerald-50 text-emerald-600 px-5 py-2 rounded-full text-[10px] font-black">{activeOrder.status}</span>
                     <p className="text-4xl font-black text-slate-950">{activeOrder.price} ج.م</p>
                  </div>
                  <div className="space-y-6 text-right">
                     <div className="flex gap-4 flex-row-reverse"><div className="bg-slate-50 p-4 rounded-2xl text-emerald-600 shadow-inner"><MapPin /></div><div className="flex-1"><p className="text-[9px] text-slate-400">نقطة الاستلام</p><p className="font-black text-lg">{activeOrder.pickup?.villageName}</p></div></div>
                     <div className="flex gap-4 flex-row-reverse"><div className="bg-rose-50 p-4 rounded-2xl text-rose-600 shadow-inner"><Navigation2 /></div><div className="flex-1"><p className="text-[9px] text-slate-400">وجهة التوصيل</p><p className="font-black text-lg">{activeOrder.dropoff?.villageName}</p></div></div>
                  </div>
                  <button onClick={() => setActiveView('MAP')} className="w-full bg-slate-900 text-emerald-400 py-6 rounded-3xl font-black flex items-center justify-center gap-4 shadow-xl"><Crosshair /> فتح الخريطة والمسار</button>
                  <div className="grid grid-cols-2 gap-4">
                     <a href={`tel:${activeOrder.customerPhone}`} className="bg-emerald-600 text-white py-5 rounded-3xl font-black flex items-center justify-center gap-3"><PhoneCall /> اتصال</a>
                     <button onClick={() => setShowChat(true)} className="bg-white border-2 border-slate-100 text-slate-900 py-5 rounded-3xl font-black flex items-center justify-center gap-3"><MessageCircle /> دردشة</button>
                  </div>
                  <button onClick={() => updateOrderStatus(activeOrder.status === OrderStatus.ACCEPTED ? OrderStatus.PICKED_UP : OrderStatus.DELIVERED)} disabled={isSubmitting} className="w-full bg-slate-950 text-white py-7 rounded-[2rem] font-black text-lg shadow-2xl">{isSubmitting ? <Loader2 className="animate-spin mx-auto" /> : activeOrder.status === OrderStatus.ACCEPTED ? 'تأكيد الاستلام' : 'تأكيد التوصيل والتحصيل'}</button>
               </div>
            ) : (
               <div className="space-y-6">
                  {availableOrders.map(o => (
                     <div key={o.id} className="bg-white p-8 rounded-[3.5rem] border-2 border-slate-50 shadow-xl space-y-6 hover:border-emerald-500 transition-all">
                        <div className="flex justify-between items-start text-right">
                           <div><p className="text-xl font-black">{o.pickup?.villageName} ← {o.dropoff?.villageName}</p><span className="text-[10px] bg-emerald-50 text-emerald-600 px-3 py-1 rounded-full">{o.requestedVehicleType}</span></div>
                           <div className="bg-slate-950 text-emerald-400 p-4 rounded-2xl font-black text-2xl">{o.price}</div>
                        </div>
                        <button onClick={() => { setShowOfferInput(o.id); setOfferPrice(o.price.toString()); }} className="w-full bg-slate-900 text-white py-6 rounded-3xl font-black shadow-xl flex items-center justify-center gap-4"><Zap className="text-emerald-400" /> تقديم عرض سعر</button>
                        {showOfferInput === o.id && (
                          <div className="pt-4 border-t border-slate-50 flex gap-2">
                             <input value={offerPrice} onChange={e => setOfferPrice(e.target.value)} type="number" className="flex-1 bg-slate-50 p-4 rounded-2xl font-black text-center outline-none" />
                             <button onClick={() => handleSendOffer(o)} className="bg-emerald-600 text-white px-8 rounded-2xl font-black">إرسال</button>
                          </div>
                        )}
                     </div>
                  ))}
               </div>
            )}
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-xl border-t border-slate-100 p-6 flex justify-around items-center z-[150] rounded-t-[3rem] shadow-[0_-10px_40px_rgba(0,0,0,0.05)]">
         {[{id: 'HOME', icon: <Home />, label: 'الرئيسية'}, {id: 'ACTIVITY', icon: <History />, label: 'سجلي'}, {id: 'PROFILE', icon: <UserIcon />, label: 'حسابي'}].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-1.5 ${activeView === tab.id ? 'text-emerald-600 scale-110' : 'text-slate-300'}`}><div className={`p-3 rounded-2xl ${activeView === tab.id ? 'bg-emerald-50 shadow-inner' : ''}`}>{tab.icon}</div><span className="text-[9px] font-black uppercase tracking-widest">{tab.label}</span></button>
         ))}
      </nav>
    </div>
  );
};

export default CourierDashboard;

import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order, Village, Offer, OrderCategory, Restaurant, MenuItem, CartItem, District, Ad } from '../types';
import { OrderStatus, VehicleType } from '../types';
import { MENOFIA_DATA, DEFAULT_PRICING } from '../config/constants';

// React Leaflet
import { MapContainer, TileLayer, Marker, Polyline, useMap } from 'react-leaflet';
import L from 'leaflet';

// Utils
import { stripFirestore, compressImage, getRoadDistance, getRouteGeometry } from '../utils';

// Services
import { db } from '../services/firebase';
import { 
  collection, addDoc, query, where, onSnapshot, 
  doc, updateDoc, orderBy
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Icons
import { 
  MapPin, Bike, Check, 
  ChevronDown, ChevronRight, Star,
  User as UserIcon, MessageCircle, Loader2,
  Bot, History, Navigation2, UtensilsCrossed, 
  ShoppingBag, ArrowRight, ThumbsUp, PartyPopper,
  Plus, Minus, PhoneCall, Pill,
  Zap, Car, X, Navigation, Map as MapIcon,
  Camera, FileText, Search, Edit2, CheckCircle2,
  Utensils, Store, Trash2, ZoomIn, Download, ChevronLeft,
  Timer, Milestone, AlertTriangle, Home, Radar, Compass
} from 'lucide-react';

// Components
import ProfileView from './ProfileView';
import ActivityView from './ActivityView';
import WalletView from './WalletView';
import ChatView from '../components/ChatView';
import AIAssistant from '../config/AIAssistant';

// --- Custom Icons ---
const driverIcon = L.divIcon({
  html: `<div class="bg-white p-2 rounded-full shadow-2xl border-4 border-emerald-500 animate-bounce text-xl flex items-center justify-center">🛵</div>`,
  className: 'live-driver-icon',
  iconSize: [40, 40],
  iconAnchor: [20, 20]
});

const MapAutoFit: React.FC<{ points: [number, number][] }> = ({ points }) => {
  const map = useMap();
  useEffect(() => {
    if (points.length > 1) { map.fitBounds(L.latLngBounds(points), { padding: [50, 50] }); }
  }, [points]);
  return null;
};

// --- Sub Components ---

const AdsSlider: React.FC<{ ads: Ad[], onAdClick: (ad: Ad) => void }> = ({ ads, onAdClick }) => {
  if (ads.length === 0) return null;
  return (
    <div className="w-full space-y-4">
       <div className="flex gap-4 overflow-x-auto no-scrollbar px-2 pb-2">
          {ads.map(ad => (
            <div key={ad.id} onClick={() => onAdClick(ad)} className="min-w-[85vw] md:min-w-[400px] aspect-[21/9] bg-slate-900 rounded-[2.5rem] relative overflow-hidden shadow-xl cursor-pointer group active:scale-95 transition-all">
               <img src={ad.imageUrl} className="absolute inset-0 w-full h-full object-cover opacity-80 group-hover:scale-105 transition-transform duration-700" alt={ad.title} />
               <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent p-6 flex flex-col justify-end text-right">
                  <h4 className="text-white font-black text-lg">{ad.title}</h4>
                  <div className="mt-2 bg-emerald-500 text-white self-end px-5 py-1.5 rounded-full font-black text-[10px]">{ad.ctaText || 'اطلب الآن'}</div>
               </div>
            </div>
          ))}
       </div>
    </div>
  );
};

const LocationSelector: React.FC<{
  label: string, helper: string, icon: React.ReactNode, iconBg: string,
  selectedDistrict: District | null, selectedVillage: Village | null,
  onSelectDistrict: (d: District) => void, onSelectVillage: (v: Village) => void,
  addressNote?: string, onAddressChange?: (val: string) => void,
  minimal?: boolean
}> = ({ label, helper, icon, iconBg, selectedDistrict, selectedVillage, onSelectDistrict, onSelectVillage, addressNote, onAddressChange, minimal = false }) => {
  const [showDistricts, setShowDistricts] = useState(false);
  const [showVillages, setShowVillages] = useState(false);
  return (
    <div className={`bg-white rounded-[2.5rem] card-shadow space-y-4 border border-slate-50 ${minimal ? 'p-4' : 'p-6'}`}>
      {!minimal && (
        <div className="flex items-center gap-4 flex-row-reverse text-right">
          <div className={`${iconBg} p-3.5 rounded-2xl text-white shadow-lg`}>{icon}</div>
          <div className="flex-1">
            <h4 className="font-black text-slate-900 text-xl">{label}</h4>
            <p className="text-[10px] font-bold text-slate-400 mt-0.5">{helper}</p>
          </div>
        </div>
      )}
      <div className="grid grid-cols-2 gap-3" dir="rtl">
        <div className="relative">
          <button onClick={() => { setShowDistricts(!showDistricts); setShowVillages(false); }} className="w-full bg-[#F8FAFC] p-4 rounded-2xl text-right flex justify-between items-center text-xs border border-slate-100 font-black truncate">{selectedDistrict?.name || "اختر المركز"}<ChevronDown className="h-4 w-4" /></button>
          {showDistricts && <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-2xl shadow-2xl z-[6000] max-h-48 overflow-y-auto border border-slate-100 animate-reveal">{MENOFIA_DATA.map(d => <button key={d.id} onClick={() => { onSelectDistrict(d); setShowDistricts(false); }} className="w-full p-4 text-right hover:bg-emerald-50 font-black text-xs border-b border-slate-50">{d.name}</button>)}</div>}
        </div>
        <div className="relative">
          <button onClick={() => { if(selectedDistrict) setShowVillages(!showVillages); setShowDistricts(false); }} disabled={!selectedDistrict} className="w-full bg-[#F8FAFC] p-4 rounded-2xl text-right flex justify-between items-center text-xs disabled:opacity-50 border border-slate-100 font-black truncate">{selectedVillage?.name || "القرية"}<ChevronDown className="h-4 w-4" /></button>
          {showVillages && selectedDistrict && <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-2xl shadow-2xl z-[6000] max-h-48 overflow-y-auto border border-slate-100 animate-reveal">{selectedDistrict.villages.map(v => <button key={v.id} onClick={() => { onSelectVillage(v); setShowVillages(false); }} className="w-full p-4 text-right hover:bg-emerald-50 font-black text-xs border-b border-slate-50">{v.name}</button>)}</div>}
        </div>
      </div>
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [pickupDistrict, setPickupDistrict] = useState<District | null>(null);
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffDistrict, setDropoffDistrict] = useState<District | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [ads, setAds] = useState<Ad[]>([]);
  const [viewingAd, setViewingAd] = useState<Ad | null>(null);
  const [viewingRestaurant, setViewingRestaurant] = useState<Restaurant | null>(null);
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [routeGeometry, setRouteGeometry] = useState<[number, number][]>([]);
  const [driverLoc, setDriverLoc] = useState<{lat: number, lng: number} | null>(null);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    onSnapshot(query(collection(db, "restaurants"), orderBy("name", "asc")), snap => setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]));
    onSnapshot(collection(db, "ads"), snap => setAds(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })).filter(ad => ad.isActive) as Ad[]));
    return onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), snapshot => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.id && activeOrder.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), snap => setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]));
    }
    if (activeOrder?.driverId) {
      return onSnapshot(doc(db, "users", activeOrder.driverId), (docSnap) => {
        if (docSnap.exists() && docSnap.data().location) {
          const loc = docSnap.data().location;
          setDriverLoc(loc);
          const target = activeOrder.status === OrderStatus.ACCEPTED ? activeOrder.pickup : activeOrder.dropoff;
          getRouteGeometry(loc.lat, loc.lng, target.lat, target.lng).then(setRouteGeometry);
        }
      });
    } else { setDriverLoc(null); setRouteGeometry([]); }
  }, [activeOrder?.id, activeOrder?.status]);

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    await updateDoc(doc(db, "orders", activeOrder.id), { driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone, driverPhoto: offer.driverPhoto || null, status: OrderStatus.ACCEPTED, acceptedAt: Date.now(), price: offer.price });
  };

  const handleCreateOrder = async () => {
    if (!dropoffVillage) return alert('اختر وجهة التوصيل');
    setIsSubmitting(true);
    try {
      const orderData = { 
        customerId: user.id, customerPhone: user.phone, category: selectedCategory, status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), paymentMethod: 'CASH',
        pickup: pickupVillage ? { address: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng, villageName: pickupVillage.name } : { address: 'موقعي', lat: 30.556, lng: 31.008, villageName: 'غير محدد' },
        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
        requestedVehicleType: 'TOKTOK', price: 30, distance: 1 
      };
      await addDoc(collection(db, "orders"), stripFirestore(orderData));
    } finally { setIsSubmitting(false); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout relative h-full w-full bg-slate-50 overflow-hidden">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />

      <div className="page-container no-scrollbar h-full overflow-y-auto">
        <div className="p-6 md:p-10 space-y-8 pb-32 max-w-2xl mx-auto">
          {!activeOrder ? (
            <>
              <div className="flex justify-between items-center"><div className="text-right"><h2 className="text-4xl font-black tracking-tighter">وصـــلــهــا</h2><p className="text-slate-400 font-bold text-[10px] uppercase mt-2">خدمة التوصيل الذكية للمنوفية</p></div><button onClick={() => setAiOpen(true)} className="p-4 bg-emerald-50 text-emerald-600 rounded-3xl active:scale-90 shadow-sm border border-emerald-100"><Bot /></button></div>
              <AdsSlider ads={ads} onAdClick={setViewingAd} />
              <div className="flex gap-4">{[{ id: 'FOOD', label: 'أكل', icon: <UtensilsCrossed /> }, { id: 'TAXI', label: 'مشوار', icon: <Bike /> }].map(cat => <button key={cat.id} onClick={() => setSelectedCategory(cat.id as any)} className={`flex-1 py-8 rounded-[2.5rem] flex flex-col items-center gap-3 bg-white card-shadow transition-all ${selectedCategory === cat.id ? 'border-4 border-emerald-500 scale-105' : 'opacity-40 grayscale'}`}>{cat.icon}<span className="text-[10px] font-black uppercase tracking-widest">{cat.label}</span></button>)}</div>
              <LocationSelector label="نقطة الانطلاق" helper="موقع استلامك" icon={<MapPin />} iconBg="bg-emerald-500" selectedDistrict={pickupDistrict} selectedVillage={pickupVillage} onSelectDistrict={setPickupDistrict} onSelectVillage={setPickupVillage} />
              <LocationSelector label="مكان التوصيل" helper="أين سيسلمك الكابتن؟" icon={<CheckCircle2 />} iconBg="bg-rose-500" selectedDistrict={dropoffDistrict} selectedVillage={dropoffVillage} onSelectDistrict={setDropoffDistrict} onSelectVillage={setDropoffVillage} />
              <button onClick={handleCreateOrder} disabled={isSubmitting || !dropoffVillage} className="w-full bg-slate-950 text-white py-7 rounded-[2.5rem] font-black text-xl shadow-2xl active:scale-95 transition-all">{isSubmitting ? <Loader2 className="animate-spin mx-auto" /> : 'اطلب مشوارك الآن'}</button>
            </>
          ) : (
            <div className="space-y-10">
               {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                 <div className="text-center space-y-8 animate-reveal">
                    <div className="bg-white p-12 rounded-full shadow-2xl inline-block border-4 border-emerald-50"><Radar className="h-20 w-20 text-emerald-600 animate-pulse" /></div>
                    <h2 className="text-3xl font-black">جاري البحث عن كباتن...</h2>
                    <div className="space-y-4">
                       {incomingOffers.map(offer => <div key={offer.id} className="bg-white p-6 rounded-[2.5rem] card-shadow flex justify-between items-center animate-reveal"><button onClick={() => handleAcceptOffer(offer)} className="bg-emerald-600 text-white px-8 py-3 rounded-2xl font-black text-xs">قبول {offer.price} ج.م</button><div className="text-right"><p className="font-black">{offer.driverName}</p><div className="flex items-center gap-1 justify-end"><span className="text-[10px] font-black text-amber-500">{offer.driverRating}</span><Star className="h-3 w-3 fill-amber-400" /></div></div></div>)}
                    </div>
                    <button onClick={() => updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED })} className="text-rose-500 font-black text-xs uppercase tracking-widest hover:underline">إلغاء الطلب</button>
                 </div>
               ) : (
                 <div className="space-y-8 animate-reveal">
                    {driverLoc && (
                      <div className="h-64 rounded-[3.5rem] overflow-hidden border-4 border-white shadow-2xl relative">
                        <MapContainer center={[driverLoc.lat, driverLoc.lng]} zoom={15} zoomControl={false} className="h-full w-full">
                          <TileLayer url="https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png" />
                          <Marker position={[driverLoc.lat, driverLoc.lng]} icon={driverIcon} />
