                      </div>
                    )}
                    <div className="bg-emerald-600 p-8 rounded-[3rem] text-white flex justify-between items-center shadow-2xl">
                       <div className="text-right"><p className="text-xs font-black opacity-60 uppercase mb-1">حالة الرحلة</p><h3 className="text-2xl font-black">{activeOrder.status}</h3></div>
                       <Navigation className="animate-bounce" />
                    </div>
                    <div className="flex flex-col items-center gap-4"><div className="w-24 h-24 bg-white rounded-[2.5rem] shadow-xl overflow-hidden border-4 border-white">{activeOrder.driverPhoto ? <img src={activeOrder.driverPhoto} className="w-full h-full object-cover" /> : <UserIcon className="h-12 w-12 mx-auto mt-6 text-slate-200" />}</div><h4 className="text-2xl font-black">{activeOrder.driverName}</h4></div>
                    <div className="grid grid-cols-2 gap-4">
                       <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-950 text-white py-6 rounded-3xl font-black flex items-center justify-center gap-3"><PhoneCall /> اتصال</a>
                       <button onClick={() => setShowChat(true)} className="bg-white border-2 border-slate-100 text-slate-900 py-6 rounded-3xl font-black flex items-center justify-center gap-3"><MessageCircle /> دردشة</button>
                    </div>
                 </div>
               )}
            </div>
          )}
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-2xl border-t border-slate-100 p-6 flex justify-around items-center z-[150] shadow-2xl flex-row-reverse rounded-t-[3rem]">
         {[{id: 'NEW', icon: <Home />, label: 'الرئيسية'}, {id: 'ACTIVITY', icon: <History />, label: 'نشاطي'}, {id: 'PROFILE', icon: <UserIcon />, label: 'حسابي'}].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-1.5 ${activeView === tab.id ? 'text-emerald-600' : 'text-slate-300'}`}><div className={`p-3.5 rounded-2xl ${activeView === tab.id ? 'bg-emerald-50 shadow-inner scale-110' : ''}`}>{tab.icon}</div><span className="text-[9px] font-black uppercase tracking-widest">{tab.label}</span></button>
         ))}
      </nav>
    </div>
  );
};

