const VillageSelector: React.FC<{
  label: string, helper: string, icon: React.ReactNode, iconBg: string,
  selectedVillage: Village | null, onSelect: (v: Village) => void
}> = ({ label, helper, icon, iconBg, selectedVillage, onSelect }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const allVillages = MENOFIA_DATA.flatMap(d => d.villages);
  const filtered = allVillages.filter(v => v.name.includes(searchTerm));

  return (
    <div className="space-y-2 relative">
      <div className="flex flex-col px-2 text-right">
        <label className="text-sm font-black text-slate-900">{label}</label>
        <span className="text-[10px] font-bold text-slate-400">{helper}</span>
      </div>
      <button onClick={() => setIsOpen(!isOpen)} className="w-full bg-white p-5 rounded-[2rem] border-2 border-slate-100 flex flex-row-reverse items-center justify-between shadow-sm active:scale-[0.98] transition-all">
        <div className="flex items-center gap-4 flex-row-reverse text-right">
          <div className={`${iconBg} p-3.5 rounded-2xl text-white shadow-lg`}>{icon}</div>
          <span className={`text-lg font-black ${selectedVillage ? 'text-slate-900' : 'text-slate-300'}`}>{selectedVillage?.name || "اختر المنطقة..."}</span>
        </div>
        <ChevronDown className={`h-5 w-5 text-slate-300 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
      </button>
      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-[2.5rem] shadow-2xl border border-slate-100 z-[5000] flex flex-col max-h-72 overflow-hidden animate-in zoom-in">
           <div className="p-4 border-b border-slate-50">
              <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="ابحث عن قريتك..." className="w-full bg-slate-50 p-4 rounded-2xl text-right font-black text-xs outline-none" dir="rtl" />
           </div>
           <div className="flex-1 overflow-y-auto no-scrollbar p-4">
              {filtered.map(v => (
                <button key={v.id} onClick={() => { onSelect(v); setIsOpen(false); }} className="w-full p-4 hover:bg-emerald-50 rounded-xl text-right font-bold text-slate-700 transition-colors">{v.name}</button>
              ))}
           </div>
        </div>
      )}
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [ads, setAds] = useState<Ad[]>([]);
  const [viewingAd, setViewingAd] = useState<Ad | null>(null);
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [viewingRestaurant, setViewingRestaurant] = useState<Restaurant | null>(null);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [routeGeometry, setRouteGeometry] = useState<[number, number][]>([]);
  const [driverLoc, setDriverLoc] = useState<{lat: number, lng: number} | null>(null);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [rating, setRating] = useState(5);
  const [feedback, setFeedback] = useState('');

  useEffect(() => {
    onSnapshot(query(collection(db, "restaurants"), orderBy("name", "asc")), snap => setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]));
    onSnapshot(collection(db, "ads"), snap => setAds(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })).filter(ad => ad.isActive) as Ad[]));
    return onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), snapshot => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.id && activeOrder.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), snap => setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]));
    }
    if (activeOrder?.driverId && activeOrder.status !== OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(doc(db, "users", activeOrder.driverId), (docSnap) => {
        if (docSnap.exists() && docSnap.data().location) {
          const loc = docSnap.data().location;
          setDriverLoc(loc);
          const target = activeOrder.status === OrderStatus.ACCEPTED ? activeOrder.pickup : activeOrder.dropoff;
          getRouteGeometry(loc.lat, loc.lng, target.lat, target.lng).then(setRouteGeometry);
        }
      });
    } else { setDriverLoc(null); setRouteGeometry([]); }
  }, [activeOrder?.id, activeOrder?.status, activeOrder?.driverId]);

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    await updateDoc(doc(db, "orders", activeOrder.id), { 
      driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone, 
      driverPhoto: offer.driverPhoto || null, status: OrderStatus.ACCEPTED, acceptedAt: Date.now(), 
      price: offer.price 
    });
  };

  const handleCreateOrder = async (extra: any = {}) => {
    if (!dropoffVillage) return alert('اختر وجهة التوصيل');
    setIsSubmitting(true);
    try {
      const dist = pickupVillage ? calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng) : 1;
      const orderData = { 
        customerId: user.id, customerPhone: user.phone, category: selectedCategory, status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), paymentMethod: 'CASH',
        pickup: pickupVillage ? { address: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng, villageName: pickupVillage.name } : { address: 'موقعي', lat: 30.556, lng: 31.008, villageName: 'غير محدد' },
        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
        requestedVehicleType: 'MOTORCYCLE', price: 30, distance: dist, ...extra
      };
      await addDoc(collection(db, "orders"), stripFirestore(orderData));
    } finally { setIsSubmitting(false); }
  };

  const calculateDistance = (lat1: number, lon1: number, lat2: number, lon2: number): number => {
    const R = 6371; const dLat = (lat2 - lat1) * (Math.PI / 180); const dLon = (lon2 - lon1) * (Math.PI / 180);
    const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) + Math.cos(lat1 * (Math.PI / 180)) * Math.cos(lat2 * (Math.PI / 180)) * Math.sin(dLon / 2) * Math.sin(dLon / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)); return parseFloat((R * c).toFixed(1));
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout relative h-full w-full bg-slate-50 overflow-hidden">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />

