              <AdsSlider ads={ads} onAdClick={() => {}} />

              {/* فئات الطلبات - استعادة الـ 3 أزرار */}
              <div className="grid grid-cols-3 gap-3">
                  {[
                    { id: 'TAXI', label: 'مشوار', icon: <Bike /> },
                    { id: 'FOOD', label: 'أكل', icon: <UtensilsCrossed /> },
                    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-6 rounded-[2rem] flex flex-col items-center gap-3 transition-all border-4 ${selectedCategory === cat.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-xl scale-105' : 'bg-white border-transparent text-slate-300 opacity-60 grayscale'}`}>
                       <div className="p-3 bg-slate-50 rounded-2xl group-hover:bg-emerald-50 transition-all">{cat.icon}</div>
                       <span className="text-[10px] font-black uppercase tracking-widest">{cat.label}</span>
                    </button>
                  ))}
              </div>

              {selectedCategory === 'FOOD' ? (
                <div className="space-y-6 animate-reveal">
                   <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest text-right px-2">المطاعم في المنوفية</h3>
                   <div className="grid grid-cols-1 gap-4">
                      {restaurants.map(rest => (
                        <div key={rest.id} className="bg-white p-5 rounded-[2.5rem] card-shadow flex flex-row-reverse justify-between items-center hover:border-emerald-500 transition-all cursor-pointer group">
                           <div className="flex items-center gap-4 flex-row-reverse text-right">
                              <div className="w-16 h-16 bg-slate-900 rounded-[1.5rem] overflow-hidden shadow-lg">
                                 {rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" /> : <Utensils className="p-5 text-emerald-400" />}
                              </div>
                              <div><h4 className="text-lg font-black text-slate-800 leading-tight">{rest.name}</h4><p className="text-[10px] font-bold text-slate-400 mt-1">{rest.category}</p></div>
                           </div>
                           <ChevronRight className="rotate-180 text-slate-200 group-hover:text-emerald-500 transition-colors" />
                        </div>
                      ))}
                   </div>
                </div>
              ) : (
                <div className="space-y-6 animate-reveal">
                   <VillageSelector label="نقطة الانطلاق" helper="موقع استلامك الآن" icon={<MapPin />} iconBg="bg-emerald-500" selectedVillage={pickupVillage} onSelect={setPickupVillage} />
                   <VillageSelector label="مكان التوصيل" helper="أين سيسلمك الكابتن؟" icon={<CheckCircle2 />} iconBg="bg-rose-500" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} />
                   <button onClick={() => handleCreateOrder()} disabled={isSubmitting || !dropoffVillage} className="w-full bg-slate-950 text-white py-7 rounded-[2.5rem] font-black text-xl shadow-2xl active:scale-95 transition-all mt-4">{isSubmitting ? <Loader2 className="animate-spin h-8 w-8 mx-auto" /> : 'اطلب رحلتك الآن'}</button>
                </div>
