                    <div className="bg-white p-12 rounded-full shadow-2xl inline-block border-4 border-emerald-50"><Radar className="h-20 w-20 text-emerald-600 animate-pulse" /></div>
                    <h2 className="text-3xl font-black text-slate-950">جاري البحث عن كباتن...</h2>
                    <div className="space-y-4">
                       {incomingOffers.map(offer => (
                         <div key={offer.id} className="bg-white p-7 rounded-[3rem] shadow-xl border-4 border-slate-50 flex justify-between items-center animate-reveal">
                            <div className="text-center space-y-2">
                               <p className="text-2xl font-black text-emerald-600">{offer.price} ج.م</p>
                               <button onClick={() => handleAcceptOffer(offer)} className="bg-emerald-600 text-white px-8 py-2 rounded-2xl font-black text-[10px]">قبول</button>
