                            <div className="flex items-center gap-4 flex-row-reverse text-right">
                               <div className="w-14 h-14 bg-slate-900 rounded-2xl flex items-center justify-center overflow-hidden">{offer.driverPhoto ? <img src={offer.driverPhoto} className="w-full h-full object-cover" /> : <UserIcon className="text-slate-500" />}</div>
                               <div><p className="font-black text-slate-800">{offer.driverName}</p><div className="flex items-center gap-1 justify-end"><span className="text-[10px] font-black text-amber-500">{offer.driverRating}</span><Star className="h-3 w-3 fill-amber-400" /></div></div>
                            </div>
                         </div>
                       ))}
                    </div>
                    <button onClick={() => updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED })} className="text-rose-500 font-black text-[10px] uppercase tracking-widest hover:underline">إلغاء الطلب</button>
