const MapAutoFit: React.FC<{ points: [number, number][] }> = ({ points }) => {
  const map = useMap();
  useEffect(() => {
    if (points.length > 1) { map.fitBounds(L.latLngBounds(points), { padding: [50, 50] }); }
  }, [points]);
  return null;
};

