import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './pages/App';

// تسجيل الـ Service Worker للإشعارات
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    // بناء المسار باستخدام النطاق الحالي المباشر لضمان عدم الخروج إلى نطاق ai.studio
    // نستخدم pathname للتعامل مع الحالات التي يكون فيها التطبيق في مجلد فرعي
    const currentPath = window.location.pathname;
    const directory = currentPath.substring(0, currentPath.lastIndexOf('/')) || '';
    const swUrl = `${window.location.origin}${directory}/firebase-messaging-sw.js`.replace(/\/+/g, '/').replace(':/', '://');

    console.log('Attempting to register SW at:', swUrl);

    navigator.serviceWorker.register(swUrl)
      .then((registration) => {
        console.log('Service Worker registered with scope:', registration.scope);
      })
      .catch((err) => {
        // محاولة بديلة في حال فشل بناء المسار المعقد
        console.warn('Advanced SW registration failed, trying simple relative path...');
        navigator.serviceWorker.register('firebase-messaging-sw.js')
          .catch((err2) => {
            console.error('Service Worker registration failed completely:', err2);
          });
      });
  });
}

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

